describe('dict admin (hand-written)', () => {
  const ENTRIES = '/api/settings/dict-entries'
  const http = () => request(app.getHttpServer())
  /** The read side every page uses (Redis `dict:` cache + version). */
  const read = (code: string) => http().get(`${URL}/${code}/entries`).set(bearer(tokens.plain))
  const entry = async (dictCode: string, value: string, over: object = {}) =>
    (
      await http()
        .post(ENTRIES)
        .set(bearer(tokens.admin))
        .send({ dictCode, value, label: `${value} label`, ...over })
        .expect(201)
    ).body.data

  it('codes are dotted lowercase and set once; per-locale names stored without blanks', async () => {
    for (const code of ['Upper.case', 'with-dash', '1.starts.with.digit'])
      await create(body(unique(), { code })).expect(400)
    const tag = unique()
    const row = await add(body(tag, { nameI18n: { 'zh-CN': '中文名', 'en-US': '  ' } }))
    expect(row.nameI18n).toEqual({ 'zh-CN': '中文名' })
    await call('admin', 'put', `/${row.id}`, {
      code: `${tag}.renamed`,
      nameI18n: { 'en-US': 'English name' },
    }).expect(200)
    expect((await call('admin', 'get', `/${row.id}`)).body.data).toMatchObject({
      code: tag,
      nameI18n: { 'en-US': 'English name' },
    })
    await call('admin', 'put', `/${row.id}`, { nameI18n: { 'zh-CN': '', 'en-US': '' } }).expect(200)
    expect((await call('admin', 'get', `/${row.id}`)).body.data.nameI18n).toBeNull()
    await create(body(unique(), { nameI18n: { fr: 'x' } })).expect(400)
  })

  it('GET /options: any signed-in user, enabled dicts by code with their names', async () => {
    const tag = unique()
    await add(body(`${tag}.b`, { nameI18n: { 'en-US': 'B' } }))
    await add(body(`${tag}.a`))
    await add(body(`${tag}.off`, { enabled: false }))
    const res = await call('plain', 'get', '/options').expect(200)
    const mine = res.body.data.filter((o: { code: string }) => o.code.startsWith(`${tag}.`))
    expect(mine).toEqual([
      { code: `${tag}.a`, name: `${tag}.a name`, nameI18n: null },
      { code: `${tag}.b`, name: `${tag}.b name`, nameI18n: { 'en-US': 'B' } },
    ])
    expect(res.body.data.map((o: { code: string }) => o.code)).toContain('core.enabled')
    await request(app.getHttpServer()).get(`${URL}/options`).expect(401)
  })

  it('every dict and entry write drops the cached entries and moves the version', async () => {
    const code = unique()
    const dict = await add(body(code))
    const first = (await read(code).expect(200)).body.data
    expect(first.entries).toEqual([])
    const seen = [first.version]
    const expectFresh = async (values: string[]) => {
      const { version, entries } = (await read(code).expect(200)).body.data
      expect(version).toBeGreaterThan(seen.at(-1)!)
      seen.push(version)
      expect(entries.map((e: { value: string }) => e.value)).toEqual(values)
    }
    const a = await entry(code, 'a', { sortNo: 2 })
    await expectFresh(['a'])
    const b = await entry(code, 'b', { sortNo: 1, labelI18n: { 'en-US': 'Bee' } })
    await expectFresh(['b', 'a'])
    await http().put(`${ENTRIES}/${b.id}`).set(bearer(tokens.admin)).send({ sortNo: 3 }).expect(200)
    await expectFresh(['a', 'b'])
    await http()
      .put(`${ENTRIES}/${a.id}/enabled`)
      .set(bearer(tokens.admin))
      .send({ enabled: false })
      .expect(200)
    await expectFresh(['b'])
    expect((await read(code)).body.data.entries[0].labelI18n).toEqual({ 'en-US': 'Bee' })
    // a disabled dict reads as none; enabled again, it is back
    await call('admin', 'put', `/${dict.id}/enabled`, { enabled: false }).expect(200)
    await read(code).expect(404)
    await call('admin', 'put', `/${dict.id}`, { enabled: true, name: 'back' }).expect(200)
    await expectFresh(['b'])
    await http().delete(`${ENTRIES}/${b.id}`).set(bearer(tokens.admin)).expect(200)
    await expectFresh([])
  })

  it('a cache fill racing a write never caches the stale entries (nor under the new version)', async () => {
    const code = unique()
    await add(body(code))
    const a = await entry(code, 'a')
    const dicts = app.get(DictService)
    // a read loads the entries, then stalls until the admin renamed one
    const query = ds.query.bind(ds)
    let loaded!: () => void
    const atGate = new Promise<void>((r) => (loaded = r))
    let release!: () => void
    const gate = new Promise<void>((r) => (release = r))
    let gated = false
    const spy = vi
      .spyOn(ds, 'query')
      .mockImplementation(async (sql: string, args?: Parameters<typeof query>[1]) => {
        const rows = await query(sql, args)
        if (
          !gated &&
          sql.includes('FROM cfg_dict_entry') &&
          Array.isArray(args) &&
          args[0] === code
        ) {
          gated = true
          loaded()
          await gate
        }
        return rows
      })
    try {
      const racing = dicts.entries(code)
      await atGate
      await http()
        .put(`${ENTRIES}/${a.id}`)
        .set(bearer(tokens.admin))
        .send({ label: 'renamed' })
        .expect(200)
      release()
      // the version moved during the load: read again, nothing cached
      expect((await racing)?.entries.map((e) => e.label)).toEqual(['renamed'])
    } finally {
      spy.mockRestore()
    }
    expect(await redis.get(redisKey('dict', 'entries', code))).toBeNull()
    const fresh = (await read(code).expect(200)).body.data
    expect(fresh.entries.map((e: { label: string }) => e.label)).toEqual(['renamed'])
    expect(fresh.version).toBe(Number(await redis.get(redisKey('dictVer', code))))
  })

  it('a dict with entries is not deleted (409 in_use, nothing deleted); without them it is', async () => {
    const used = await add(body(unique()))
    const empty = await add(body(unique()))
    const e = await entry(used.code, 'x')
    for (const res of [
      await call('admin', 'delete', `/${used.id}`),
      await call('admin', 'post', '/batch-delete', { ids: [empty.id, used.id] }),
    ]) {
      expect(res.status).toBe(409)
      expect(res.body.code).toBe(Err.IN_USE.code)
    }
    await call('admin', 'get', `/${empty.id}`).expect(200)
    // a deleted (soft) entry does not count
    await http().delete(`${ENTRIES}/${e.id}`).set(bearer(tokens.admin)).expect(200)
    await call('admin', 'post', '/batch-delete', { ids: [empty.id, used.id] }).expect(200)
    await read(used.code).expect(404)
    // the code is free again; the deleted entries stay out of the new dict
    await add(body(used.code, { name: 'again' }))
    expect((await read(used.code).expect(200)).body.data.entries).toEqual([])
  })

  it('POST /refresh-cache: every dict re-read (e.g. after SQL), modify only, action-logged', async () => {
    const code = unique()
    await add(body(code))
    await entry(code, 'a')
    const before = (await read(code).expect(200)).body.data
    // a change behind the API's back stays cached until the refresh
    await ds.query("UPDATE cfg_dict_entry SET label = 'sql' WHERE dict_code = ?", [code])
    expect((await read(code)).body.data).toEqual(before)
    await call('reader', 'post', '/refresh-cache').expect(403)
    const traceId = `${PREFIX}${process.pid}-refresh`
    await call('admin', 'post', '/refresh-cache').set('X-Request-Id', traceId).expect(200)
    const after = (await read(code).expect(200)).body.data
    expect(after.version).toBeGreaterThan(before.version)
    expect(after.entries[0].label).toBe('sql')
    expect(await logOf(ds, traceId)).toMatchObject({
      domain: 'settings.dict',
      verb: 'refresh-cache',
      ok: 1,
    })
  })
})
